public class OpenTelemetryChatModelListener implements ChatModelListener {
  private final Tracer tracer;

  @Override
  public void onRequest(ChatModelRequestContext context) {
    Span span = tracer.spanBuilder("chat_model.generate")
      .setSpanKind(SpanKind.CLIENT)
      .setAttribute("gen_ai.system", extractProvider(context))
      .setAttribute("gen_ai.request.model", context.request().modelName())
      .startSpan();
  }
}

public class OpenTelemetryMetricsCollector {
  private final LongCounter requestCounter;
  private final DoubleHistogram durationHistogram;
  private final LongCounter tokenCounter;

  public OpenTelemetryMetricsCollector(Meter meter) {
    this.requestCounter = meter.counterBuilder("langchain4j.aiservice.requests")
      .setDescription("Number of AiService requests")
      .build();
  }

  public void recordRequest(String provider, String model) {
    requestCounter.add(1, 
      Attributes.of(AttributeKey.stringKey("provider"), provider,
                   AttributeKey.stringKey("model"), model));
  }
}

public class ContentRedactionConfig {
  private boolean contentCaptureEnabled = false;
  private int maxContentLength = 1024;

  public String redactContent(String content) {
    if (!contentCaptureEnabled) {
      return "[REDACTED]";
    }
    if (content.length() > maxContentLength) {
      return content.substring(0, maxContentLength) + "...";
    }
    return content;
  }
}

@Configuration
@ConditionalOnClass(OpenTelemetry.class)
@EnableConfigurationProperties(OpenTelemetryProperties.class)
public class OpenTelemetryAutoConfiguration {

  @Bean
  @ConditionalOnMissingBean
  public OpenTelemetryAiServiceListener openTelemetryAiServiceListener(OpenTelemetry openTelemetry) {
    return new OpenTelemetryAiServiceListener(openTelemetry.getTracer("langchain4j"));
  }
}

public class TelemetryMcpServer extends BaseMcpServer {
  private final OpenTelemetryManager telemetryManager;

  @Override
  public CompletableFuture<CallToolResult> callTool(CallToolRequest request) {
    switch (request.name()) {
      case "toggle_telemetry":
        return handleToggleTelemetry(request);
      case "get_traces":
        return handleGetTraces(request);
      default:
        return super.callTool(request);
    }
  }
}

public class LangChain4jSamplingStrategy implements SamplingStrategy {
  private final double samplingRate;

  @Override
  public SamplingResult shouldSample(Context parentContext, TraceId traceId, String name, SpanKind spanKind, Attributes attributes, List<LinkData> parentLinks) {
    if (ThreadLocalRandom.current().nextDouble() < samplingRate) {
      return SamplingResult.create(SamplingDecision.RECORD_AND_SAMPLE);
    }
    return SamplingResult.create(SamplingDecision.DROP);
  }
}
